<?php require_once __DIR__.'/functions.php'; require_once __DIR__.'/app_init.php'; require_login();$pdo=dogvive_db();if($_SERVER['REQUEST_METHOD']==='POST'){try{$type=trim((string)($_POST['tipo']??''));$subject=trim((string)($_POST['asunto']??''));$desc=trim((string)($_POST['descripcion']??''));$email=strtolower(trim((string)($_POST['correo']??'')));if(!in_array($type,['Petición','Queja','Reclamo','Sugerencia','Denuncia'],true)||$subject===''||mb_strlen($desc)<10||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Completa todos los campos y escribe una descripción de al menos 10 caracteres.');$q=$pdo->prepare('INSERT INTO reporte (Tipo,Descripcion,Fecha,Estado,id_usuario) VALUES (?,?,CURDATE(),?,?)');$q->execute([$type,$subject.' — '.$desc.' | Contacto: '.$email,'Pendiente',dogvive_user_id()]);dogvive_notice($pdo,dogvive_user_id(),'PQRSD','Tu solicitud fue recibida con número de radicado '.$pdo->lastInsertId().'.');dogvive_flash('success','Tu solicitud quedó guardada.');header('Location: '.base_url().'/pqrsd.php');exit;}catch(Throwable $e){dogvive_flash('error',$e instanceof RuntimeException?$e->getMessage():'No se pudo guardar tu solicitud.');header('Location: '.base_url().'/pqrsd.php');exit;}}
start_app('PQRSD','pqrsd');page_wrap_start('PQRSD','Peticiones, quejas, reclamos, sugerencias y denuncias.');$success=dogvive_flash('success');$error=dogvive_flash('error');if($success)echo '<div class="notice">'.e($success).'</div>';if($error)echo '<div class="error-box">'.e($error).'</div>';$q=$pdo->prepare('SELECT * FROM reporte WHERE id_usuario=? ORDER BY id_reporte DESC');$q->execute([dogvive_user_id()]);$reports=$q->fetchAll(); ?>
<div class="grid grid-2"><div class="form-box card"><h3>Crear solicitud</h3><form method="post"><label>Tipo<select name="tipo" required><option>Petición</option><option>Queja</option><option>Reclamo</option><option>Sugerencia</option><option>Denuncia</option></select></label><label>Asunto<input name="asunto" maxlength="120" required></label><label>Descripción<textarea name="descripcion" rows="5" minlength="10" required></textarea></label><label>Correo de contacto<input type="email" name="correo" value="<?= e((string)($_SESSION['dogvibe_user']['correo']??'')) ?>" required></label><button class="btn btn-primary full" type="submit">Enviar PQRSD</button></form></div><div class="card"><h3>Mis solicitudes</h3><?php if(!$reports): ?><p class="muted">Todavía no tienes solicitudes registradas.</p><?php else: foreach($reports as $r): ?><div class="notification"><div class="grow"><strong>#<?= (int)$r['id_reporte'] ?> · <?= e((string)$r['Tipo']) ?></strong><p class="muted"><?= e((string)$r['Descripcion']) ?></p><small><?= e((string)$r['Fecha']) ?> · <?= e((string)$r['Estado']) ?></small></div></div><?php endforeach; endif; ?></div></div><?php page_wrap_end();end_app();
